mapper.select:
SELECT * FROM kpis_information
WHERE cycle_id = #{cycleId} 
  AND master_kpi_id = #{masterKpiId}
  AND deleted_at IS NULL
LIMIT 1

mapper.insert:
INSERT INTO kpis_information (
    id, cycle_id, master_kpi_id,
    target_description, target_value, weight, is_important,
    created_by, updated_by
) VALUES (
    #{id}, #{cycleId}, #{masterKpiId},
    CAST(#{targetDescription} AS jsonb), #{targetValue}, #{weight}, #{isImportant},
    #{createdBy}, #{createdBy}
)

mapper.update:
UPDATE kpis_information
SET deleted_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{updatedBy}
WHERE id = #{kpiInfoId}
  AND deleted_at IS NULL
